import {escape} from './ui.js';
const tags=new Set(['p','h2','h3','h4','strong','b','em','i','u','s','blockquote','ul','ol','li','a','br','hr','span']);
const discard=new Set(['script','style','iframe','object','embed','svg','math','template','form','input','button','textarea','select']);
const classes=new Set(['text-clay','text-chocolate','text-olive','align-left','align-center','align-right','align-justify','font-editorial','font-modern','font-classic']);
export function sanitizeRichHTML(html){const doc=document.createElement('template');doc.innerHTML=String(html||'');function clean(node){if(node.nodeType===3)return escape(node.textContent);if(node.nodeType!==1)return '';let tag=node.tagName.toLowerCase();if(tag==='div')tag='p';if(tag==='h1')tag='h2';if(discard.has(tag))return '';const inner=[...node.childNodes].map(clean).join('');if(!tags.has(tag))return inner;let attrs='';if(tag==='a'){try{const raw=node.getAttribute('href')||'',u=new URL(raw,location.origin);if(u.protocol==='https:'||(u.origin===location.origin&&u.protocol==='http:'))attrs=` href="${escape(u.href)}" rel="noopener noreferrer"`;}catch{}}const safe=[...node.classList].filter(x=>classes.has(x));if(safe.length)attrs+=` class="${safe.join(' ')}"`;return `<${tag}${attrs}>${['br','hr'].includes(tag)?'':inner+`</${tag}>`}`;}return [...doc.content.childNodes].map(clean).join('');}
export function plainToHTML(text){return String(text||'').split(/\n\s*\n/).map(x=>'<p>'+escape(x).replace(/\n/g,'<br>')+'</p>').join('');}
export function editorMarkup(){return `<section class="rich-composer full" aria-label="Article editor"><div class="composer-heading"><strong>Article studio</strong><span>Write. Refine. Publish.</span></div><div class="rich-toolbar" role="toolbar" aria-label="Text formatting"><select id="rich-block" aria-label="Paragraph style"><option value="p">Paragraph</option><option value="h2">Heading 2</option><option value="h3">Heading 3</option><option value="blockquote">Quote</option></select><button type="button" data-rich="strong" aria-label="Bold"><b>B</b></button><button type="button" data-rich="em" aria-label="Italic"><i>I</i></button><button type="button" data-rich="u" aria-label="Underline"><u>U</u></button><button type="button" data-rich="s" aria-label="Strikethrough"><s>S</s></button><span class="toolbar-divider"></span><button type="button" data-rich="ul" aria-label="Bullet list">• List</button><button type="button" data-rich="ol" aria-label="Numbered list">1. List</button><button type="button" data-rich="link" aria-label="Insert link">↗ Link</button><button type="button" data-rich="unlink" aria-label="Remove link">Unlink</button><select id="rich-color" aria-label="Text colour"><option value="">Text colour</option><option value="text-chocolate">Chocolate</option><option value="text-clay">Clay</option><option value="text-olive">Olive</option></select><select id="rich-align" aria-label="Text alignment"><option value="align-left">Left</option><option value="align-center">Centre</option><option value="align-right">Right</option><option value="align-justify">Justify</option></select><select id="rich-font" aria-label="Font"><option value="font-modern">Modern sans</option><option value="font-editorial">Editorial serif</option><option value="font-classic">Classic serif</option></select><button type="button" data-rich="clear" aria-label="Clear formatting">Clear</button><button type="button" data-rich="undo" aria-label="Undo">↶</button><button type="button" data-rich="redo" aria-label="Redo">↷</button><button type="button" data-rich="replace">Find / replace</button><button type="button" data-rich="expand" aria-label="Expand editor">⤢</button><button type="button" data-rich="preview" aria-pressed="false">Preview</button></div><div class="rich-document prose article-body" id="rich-document" contenteditable="true" role="textbox" aria-label="Article body" aria-multiline="true" spellcheck="true"></div><div id="rich-preview" class="rich-document prose article-body" hidden></div><div class="rich-footer"><span id="rich-count">0 words</span><span>Ctrl/⌘ B · bold &nbsp; Ctrl/⌘ I · italic</span></div><div class="rich-replace-fields" id="rich-replace-fields" hidden><label>Find<input id="rich-find-text" type="text"></label><label>Replace with<input id="rich-replace-text" type="text"></label><button type="button" class="btn small" id="rich-replace-apply">Replace all</button></div><div class="rich-link-fields" id="rich-link-fields" hidden><label>Link address<input id="rich-link-url" type="url" placeholder="https://…"></label><button class="btn small" type="button" id="rich-link-apply">Apply link</button></div></section>`;}
export function setupRichEditor(html,text){const box=document.querySelector('#rich-document');box.innerHTML=sanitizeRichHTML(html||plainToHTML(text))||'<p><br></p>';let saved=null,history=[box.innerHTML],index=0,timer;const count=()=>{const t=box.innerText.trim();if(document.querySelector('#rich-count'))document.querySelector('#rich-count').textContent=(t?t.split(/\s+/).length:0)+' words · '+t.length+' characters';};const remember=()=>{const s=window.getSelection();if(s.rangeCount&&box.contains(s.anchorNode))saved=s.getRangeAt(0).cloneRange();};const restore=()=>{box.focus();const s=window.getSelection();s.removeAllRanges();if(saved&&box.contains(saved.commonAncestorContainer))s.addRange(saved);else{const r=document.createRange();r.selectNodeContents(box);r.collapse(false);s.addRange(r);saved=r;}};const record=()=>{if(history[index]!==box.innerHTML){history=history.slice(0,index+1);history.push(box.innerHTML);if(history.length>80)history.shift();index=history.length-1;}count();};box.addEventListener('input',()=>{clearTimeout(timer);timer=setTimeout(record,250);count();});box.addEventListener('keyup',remember);box.addEventListener('mouseup',remember);box.addEventListener('blur',remember);
function range(){restore();return window.getSelection().getRangeAt(0);}
function wrap(tag,cls){const r=range();if(r.collapsed)return;const closest=(r.startContainer.nodeType===1?r.startContainer:r.startContainer.parentElement).closest(tag);if(closest&&box.contains(closest)&&tag!=='span'){closest.replaceWith(...closest.childNodes);}else{const el=document.createElement(tag);if(cls)el.className=cls;el.append(r.extractContents());r.insertNode(el);r.selectNodeContents(el);window.getSelection().removeAllRanges();window.getSelection().addRange(r);}remember();record();}
function blocks(){const r=range();return [...box.querySelectorAll('p,h2,h3,h4,blockquote,li,div')].filter(n=>r.intersectsNode(n));}
function command(cmd){if(cmd==='expand'){document.querySelector('#editor-modal').classList.toggle('editor-fullscreen');return;}if(cmd==='replace'){const p=document.querySelector('#rich-replace-fields');p.hidden=!p.hidden;if(!p.hidden)document.querySelector('#rich-find-text').focus();return;}if(cmd==='undo'||cmd==='redo'){record();index=Math.max(0,Math.min(history.length-1,index+(cmd==='undo'?-1:1)));box.innerHTML=history[index];saved=null;count();box.focus();return;}if(cmd==='preview'){record();const p=document.querySelector('#rich-preview');p.hidden=!p.hidden;box.hidden=!p.hidden;p.innerHTML=sanitizeRichHTML(box.innerHTML);document.querySelector('[data-rich="preview"]').setAttribute('aria-pressed',String(!p.hidden));return;}if(cmd==='link'){remember();document.querySelector('#rich-link-fields').hidden=false;document.querySelector('#rich-link-url').focus();return;}if(cmd==='unlink'){const r=range(),node=(r.startContainer.nodeType===1?r.startContainer:r.startContainer.parentElement).closest('a');if(node&&box.contains(node))node.replaceWith(...node.childNodes);record();return;}if(cmd==='clear'){const r=range();if(!r.collapsed){const text=document.createTextNode(r.toString());r.deleteContents();r.insertNode(text);}record();return;}if(cmd==='ul'||cmd==='ol'){const selected=blocks();if(!selected.length)return;const list=document.createElement(cmd);selected[0].before(list);for(const node of selected){const item=document.createElement('li');item.append(...node.childNodes);list.append(item);node.remove();}saved=null;record();return;}wrap(cmd);}
document.querySelectorAll('[data-rich]').forEach(button=>{button.addEventListener('mousedown',event=>event.preventDefault());button.addEventListener('click',()=>command(button.dataset.rich));});document.querySelector('#rich-block').addEventListener('change',event=>{for(const block of blocks()){const n=document.createElement(event.target.value);n.append(...block.childNodes);block.replaceWith(n);}saved=null;record();});document.querySelector('#rich-color').addEventListener('change',event=>{if(event.target.value)wrap('span',event.target.value);});document.querySelector('#rich-align').addEventListener('change',event=>{for(const b of blocks()){b.classList.remove('align-left','align-center','align-right','align-justify');b.classList.add(event.target.value);}record();});document.querySelector('#rich-font').addEventListener('change',event=>{for(const b of blocks()){b.classList.remove('font-modern','font-editorial','font-classic');b.classList.add(event.target.value);}record();});document.querySelector('#rich-link-apply').addEventListener('click',()=>{try{const u=new URL(document.querySelector('#rich-link-url').value,location.origin);if(u.protocol!=='https:')throw new Error();const r=range(),a=document.createElement('a');a.href=u.href;a.rel='noopener noreferrer';if(r.collapsed)a.textContent=u.hostname;else a.append(r.extractContents());r.insertNode(a);remember();record();document.querySelector('#rich-link-fields').hidden=true;}catch{document.querySelector('#editor-status').textContent='Use a valid HTTPS link.';}});
document.querySelector('#rich-replace-apply').addEventListener('click',()=>{const needle=document.querySelector('#rich-find-text').value,replacement=document.querySelector('#rich-replace-text').value;if(!needle)return;const walker=document.createTreeWalker(box,NodeFilter.SHOW_TEXT);while(walker.nextNode())walker.currentNode.nodeValue=walker.currentNode.nodeValue.split(needle).join(replacement);record();});
box.addEventListener('paste',event=>{event.preventDefault();const text=event.clipboardData.getData('text/plain'),r=range();r.deleteContents();const fragment=document.createDocumentFragment();text.split('\n').forEach((line,i)=>{if(i)fragment.append(document.createElement('br'));fragment.append(document.createTextNode(line));});const last=fragment.lastChild;r.insertNode(fragment);r.setStartAfter(last);r.collapse(true);saved=r;restore();record();});box.addEventListener('drop',event=>{event.preventDefault();const text=event.dataTransfer?.getData('text/plain');if(text){const r=range();r.deleteContents();r.insertNode(document.createTextNode(text));record();}});box.addEventListener('keydown',event=>{if((event.ctrlKey||event.metaKey)&&['b','i','u','z'].includes(event.key.toLowerCase())){event.preventDefault();command({b:'strong',i:'em',u:'u',z:event.shiftKey?'redo':'undo'}[event.key.toLowerCase()]);}});count();}
export function readRichEditor(){const box=document.querySelector('#rich-document');return {body:box.innerText.trim(),bodyHtml:sanitizeRichHTML(box.innerHTML)};}
